import test from 'node:test';
import assert from 'node:assert/strict';
import { normalizeConfig } from '../src/config.js';
import { validate } from '../src/index.js';

test('config defaults are explicit and immutable', () => {
  const config = normalizeConfig();
  assert.deepEqual(config, { abortEarly: false, allowUnknown: false });
  assert.equal(Object.isFrozen(config), true);
});
test('abortEarly returns one error', () => {
  const schema = { type: 'object', properties: { a: { type: 'string' }, b: { type: 'number' } } };
  assert.equal(validate({}, schema, { abortEarly: true }).errors.length, 1);
});
test('allowUnknown is opt-in', () => {
  assert.equal(validate({ extra: 1 }, { type: 'object' }, { allowUnknown: true }).valid, true);
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { validate } from '../src/index.js';

test('strings enforce bounds and type without coercion', () => {
  const schema = { type: 'string', minLength: 2, maxLength: 4 };
  assert.equal(validate('abc', schema).valid, true);
  for (const input of ['a', 'abcde', 42, null]) assert.equal(validate(input, schema).valid, false);
});
test('enumerations reject unlisted values', () => {
  const schema = { type: 'string', enum: ['draft', 'published'] };
  assert.equal(validate('draft', schema).valid, true);
  assert.equal(validate('admin', schema).valid, false);
});
test('numbers are finite and respect bounds and integer constraints', () => {
  const schema = { type: 'number', min: 0, max: 100, integer: true };
  for (const input of [0, 15, 100]) assert.equal(validate(input, schema).valid, true);
  for (const input of [-1, 101, 1.5, NaN, Infinity, '10', null]) assert.equal(validate(input, schema).valid, false);
});
test('booleans do not coerce strings or numbers', () => {
  for (const input of [true, false]) assert.equal(validate(input, { type: 'boolean' }).valid, true);
  for (const input of ['false', 0, null]) assert.equal(validate(input, { type: 'boolean' }).valid, false);
});
test('required fields distinguish missing from false and zero', () => {
  const schema = { type: 'object', properties: { enabled: { type: 'boolean' }, count: { type: 'number' } } };
  assert.equal(validate({ enabled: false, count: 0 }, schema).valid, true);
  assert.equal(validate({}, schema).errors.length, 2);
});
test('unknown object fields are rejected by default', () => {
  const result = validate({ name: 'Ada', admin: true }, { type: 'object', properties: { name: { type: 'string' } } });
  assert.equal(result.valid, false);
  assert.equal(result.errors[0].path, '$.admin');
});
test('inherited properties cannot satisfy required fields', () => {
  const schema = { type: 'object', properties: { name: { type: 'string' } } };
  assert.equal(validate(Object.create({ name: 'Ada' }), schema).valid, false);
});
test('nested validation reports the failing path', () => {
  const schema = { type: 'object', properties: { user: { type: 'object', properties: { age: { type: 'number', min: 0 } } } } };
  assert.equal(validate({ user: { age: -1 } }, schema).errors[0].path, '$.user.age');
});
test('optional fields may be absent but present values must validate', () => {
  const schema = { type: 'string', required: false };
  assert.equal(validate(undefined, schema).valid, true);
  assert.equal(validate(2, schema).valid, false);
});
test('unsupported schema types throw', () => {
  assert.throws(() => validate('x', { type: 'magic' }), TypeError);
});
